y=lanter_is_read_only($connection);$showDatabaseSwitch=$connection!==null&&lanter_driver_kind($connection)!=='sqlite'&&($connection['database']??'')!=='';$driverLabel=$connection!==null?lanter_driver_label($connection):null;$statusLabel=$driverLabel!==null&&($connection['database']??'')!==''?$driverLabel.' · '.$connection['database']:$driverLabel;$isActiveView=$activeTable!==null&&in_array($activeTable,$views,true);$activeRowCount=$activeTable!==null&&isset($tableCounts[$activeTable])?lanter_format_count($tableCounts[$activeTable]).' rows':null;$notice=$_GET['notice']??null;$error=$_GET['error']??null;$csrfToken=lanter_csrf_token();?><!DOCTYPE html>
